public class CiSearchTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        String[] words = {"Ant", "bee", "Cat", "dog", "Emu"};
        try {
            check("exact-case match", 3, CiSearch.find(words, "dog"));
            check("different case still found", 3, CiSearch.find(words, "DOG"));
            check("mixed-case target", 2, CiSearch.find(words, "cAt"));
            check("first element", 0, CiSearch.find(words, "ant"));
            check("last element", 4, CiSearch.find(words, "emu"));
            check("absent word gives -1", -1, CiSearch.find(words, "fox"));
            check("absent word before all gives -1", -1, CiSearch.find(words, "aardvark"));
            check("empty array gives -1", -1, CiSearch.find(new String[0], "x"));
        } catch (Exception e) {
            System.out.println("FAIL  unexpected exception -- " + e.getClass().getSimpleName());
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

