public class CiSearch {

    public static int find(String[] sortedCaseInsensitive, String target) {
        int index = java.util.Arrays.binarySearch(
                sortedCaseInsensitive, target, String.CASE_INSENSITIVE_ORDER);
        return index >= 0 ? index : -1;
    }
}
